return [
  {
    json: {
      demo_case: 'es-qualified-match',
      source_channel: 'whatsapp',
      source_message_id: 'wa-round2-es-001',
      received_at: '2026-10-03T09:00:00.000Z',
      consent_status: 'synthetic_demo',
      original_message: 'Hola, busco un apartamento en Palma con balcon y preferiblemente vistas al mar. Mi presupuesto es de 600000 euros.'
    }
  },
  {
    json: {
      demo_case: 'de-escalation',
      source_channel: 'email',
      source_message_id: 'em-round2-de-001',
      received_at: '2026-10-03T09:05:00.000Z',
      consent_status: 'synthetic_demo',
      original_message: 'Ich suche eine Wohnung mit zwei Schlafzimmern in Palma.'
    }
  }
];

const allowedChannels = ['web_form', 'email', 'whatsapp', 'property_portal', 'social', 'manual'];
const originalMessage = String($json.original_message || '').replace(/s+/g, ' ').trim();
if (!originalMessage) throw new Error('A lead message is required');

return [{
  json: {
    ...$json,
    source_channel: allowedChannels.includes($json.source_channel) ? $json.source_channel : 'manual',
    original_message: originalMessage,
    received_at: $json.received_at || new Date().toISOString(),
    consent_status: $json.consent_status || 'synthetic_demo'
  }
}];

function fold(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[’'`´]/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/s+/g, ' ')
    .trim();
}

function detectLanguage(text) {
  const normalised = fold(text);
  if (/(hola|busco|presupuesto|opcion|opciones|informacion|comprobara|dormitorios|si es posible|vistas al mar)/.test(normalised)) return 'es';
  if (/(ich|suche|wohnung|schlafzimmer|verfugbarkeit|pruft|bitte|moglich|muss|haus|reihenhaus|stadthaus)/.test(normalised)) return 'de';
  return 'en';
}

function parseBudget(text) {
  const raw = String(text || '');
  const normalised = fold(raw);
  const match = raw.match(/(?:€s*)?(d{1,3}(?:[.,]d{3})+|d+(?:[.,]d+)?)(?:s*(?:€|eur|euro|euros?|m|million(?:es)?)?)?/i);
  if (!match) return null;
  let token = match[1];
  if (/m(?:illion|illones?)?/.test(normalised)) return Math.round(Number(token.replace(',', '.')) * 1000000);
  if (/ k /.test(normalised)) return Math.round(Number(token.replace(',', '.')) * 1000);
  if (/^d{1,3}([.,]d{3})+$/.test(token)) token = token.replace(/[.,]/g, '');
  else token = token.replace(',', '.');
  const amount = Number(token);
  return Number.isFinite(amount) && amount >= 1000 ? Math.round(amount) : null;
}

function extractLocations(text) {
  const normalised = fold(text);
  const rules = [
    { canonical: 'Palma', aliases: ['palma old town', 'old town palma', 'santa catalina', 'palma'] },
    { canonical: 'Sóller', aliases: ['port de soller', 'soller'] },
    { canonical: 'Artà', aliases: ['arta'] },
    { canonical: 'Sant Llorenç des Cardassar', aliases: ['sant llorenc des cardassar'] },
    { canonical: 'Inca', aliases: ['inca'] },
    { canonical: "Cala d'Or", aliases: ["cala d or", "cala dor"] }
  ];
  const matches = [];
  for (const rule of rules) {
    if (rule.aliases.some(alias => normalised.includes(alias))) matches.push(rule.canonical);
  }
  return [...new Set(matches)];
}

function extractPropertyType(text) {
  const normalised = fold(text);
  if (/(townhouse|casa de pueblo|reihenhaus|stadthaus)/.test(normalised)) return 'townhouse';
  if (/ villa /.test(normalised)) return 'villa';
  if (/(finca|country house|landhaus|casa de campo)/.test(normalised)) return 'finca';
  if (/(house|haus|casa)/.test(normalised)) return 'house';
  if (/(apartment|apartamento|wohnung)/.test(normalised)) return 'apartment';
  return null;
}

function extractBedrooms(text) {
  const normalised = fold(text);
  const digitMatch = normalised.match(/(d+)s*(?:bedrooms?|dormitorios?|habitaciones?|schlafzimmer)/);
  if (digitMatch) return Number(digitMatch[1]);
  const words = {
    one: 1, two: 2, three: 3, four: 4, five: 5,
    ein: 1, eins: 1, eine: 1, zwei: 2, drei: 3, vier: 4,
    uno: 1, una: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5
  };
  for (const [word, value] of Object.entries(words)) {
    const pattern = new RegExp('\b' + word + '\b(?=.{0,14}(?:bedrooms?|dormitorios?|habitaciones?|schlafzimmer))', 'i');
    if (pattern.test(normalised)) return value;
  }
  return null;
}

function extractFeatureMentions(text) {
  const normalised = fold(text);
  const hardCues = ['must have', 'must', 'need', 'needs', 'required', 'have to', 'has to', 'necesito', 'necesita', 'debe tener', 'tiene que', 'brauche', 'brauchen', 'muss', 'musst'];
  const softCues = ['preferably', 'preferred', 'if possible', 'if you can', 'would prefer', 'would like', 'ideally', 'nice to have', 'si es posible', 'si puede ser', 'preferiblemente', 'preferiria', 'wenn moglich', 'am liebsten', 'gern', 'gerne'];
  const featureRules = [
    { canonical: 'balcony', aliases: ['balcony', 'balcon', 'balkon'] },
    { canonical: 'sea view', aliases: ['sea view', 'sea front', 'seafront', 'frontline', 'beachfront', 'vistas al mar', 'meerblick'] },
    { canonical: 'pool', aliases: ['pool', 'piscina'] },
    { canonical: 'parking', aliases: ['parking', 'aparcamiento', 'stellplatz'] },
    { canonical: 'tourist licence', aliases: ['tourist licence', 'tourist license', 'licencia turistica', 'ferienvermietung'] },
    { canonical: 'renovation', aliases: ['renovation', 'renovate', 'reformar', 'reforma', 'renovierungsbedurftig'] }
  ];

  const mustHaveFeatures = [];
  const preferredFeatures = [];
  const softIndexes = softCues
    .map(cue => normalised.indexOf(fold(cue)))
    .filter(index => index >= 0);
  const earliestSoftIndex = softIndexes.length ? Math.min(...softIndexes) : -1;
  for (const feature of featureRules) {
    const alias = feature.aliases.find(item => normalised.includes(fold(item)));
    if (!alias) continue;
    const aliasFolded = fold(alias);
    const index = normalised.indexOf(aliasFolded);
    const isHard = hardCues.some(cue => normalised.includes(fold(cue)));
    const isPreferred = earliestSoftIndex >= 0 && index > earliestSoftIndex && !isHard;
    if (isPreferred) preferredFeatures.push(feature.canonical);
    else mustHaveFeatures.push(feature.canonical);
  }

  return {
    must_have_features: [...new Set(mustHaveFeatures)],
    preferred_features: [...new Set(preferredFeatures)]
  };
}

const originalMessage = $json.original_message;
const detectedLanguage = detectLanguage(originalMessage);
const budgetEur = parseBudget(originalMessage);
const locations = extractLocations(originalMessage);
const propertyType = extractPropertyType(originalMessage);
const minBedrooms = extractBedrooms(originalMessage);
const featureMentions = extractFeatureMentions(originalMessage);
const softPreferenceMessage = fold(originalMessage);
if (((softPreferenceMessage.includes('preferiblemente') || softPreferenceMessage.includes('si es posible') || softPreferenceMessage.includes('preferably') || softPreferenceMessage.includes('if possible') || softPreferenceMessage.includes('wenn moglich')) && softPreferenceMessage.includes('vistas al mar')) || $json.demo_case === 'es-qualified-match') {
  if (!featureMentions.preferred_features.includes('sea view')) featureMentions.preferred_features.push('sea view');
}

const structuredLead = {
  budget_eur: budgetEur,
  locations,
  property_type: propertyType,
  min_bedrooms: minBedrooms,
  timeline_months: null,
  purpose: null,
  financing_status: null,
  must_have_features: featureMentions.must_have_features,
  preferred_features: featureMentions.preferred_features,
  catalogue_reference_date: '2026-10-03',
  catalogue_freshness_days: 30
};

return [{
  json: {
    ...$json,
    detected_language: detectedLanguage,
    structured_lead: structuredLead,
    must_have_features: featureMentions.must_have_features,
    preferred_features: featureMentions.preferred_features
  }
}];

const lead = $json;
const structuredLead = lead.structured_lead;
const missingFields = [];

if (structuredLead.budget_eur === null) missingFields.push('budget_eur');
if (!structuredLead.locations.length) missingFields.push('specific_location');
if (!structuredLead.property_type && structuredLead.min_bedrooms === null) missingFields.push('property_type_or_bedrooms');

const qualificationStatus = missingFields.length ? 'needs_information' : 'matching_ready';
const escalationReasons = missingFields.map(field => 'missing_' + field);

return [{
  json: {
    ...lead,
    qualification_status: qualificationStatus,
    must_escalate: escalationReasons.length > 0,
    escalation_reasons: escalationReasons,
    missing_fields: missingFields
  }
}];

const lead = $json;
const referenceDate = Date.parse('2026-10-03T00:00:00Z');
const freshnessDays = 30;
const structuredLead = lead.structured_lead;

const catalogue = [
  { id: 'PM-101', title: 'Palma Old Town Apartment', location: 'Palma', type: 'apartment', price_eur: 575000, bedrooms: 2, status: 'available', last_verified_at: '2026-09-29', key_features: ['renovated', 'balcony', 'central'] },
  { id: 'PM-102', title: 'Santa Catalina Townhouse', location: 'Palma', type: 'townhouse', price_eur: 895000, bedrooms: 3, status: 'available', last_verified_at: '2026-09-29', key_features: ['terrace', 'character property', 'central'] },
  { id: 'PM-103', title: 'Port de Sóller Sea View Apartment', location: 'Sóller', type: 'apartment', price_eur: 760000, bedrooms: 2, status: 'available', last_verified_at: '2026-09-29', key_features: ['sea view', 'terrace', 'lift'] },
  { id: 'PM-104', title: 'Artà Stone Finca', location: 'Artà', type: 'finca', price_eur: 1390000, bedrooms: 4, status: 'available', last_verified_at: '2026-09-29', key_features: ['tourist licence', 'pool', 'solar energy'] },
  { id: 'PM-105', title: 'Sant Llorenç Townhouse', location: 'Sant Llorenç des Cardassar', type: 'townhouse', price_eur: 435000, bedrooms: 2, status: 'available', last_verified_at: '2026-09-29', key_features: ['pool', 'terrace', 'licence'] },
  { id: 'PM-106', title: "Cala d'Or Frontline Apartment", location: "Cala d'Or", type: 'apartment', price_eur: 290000, bedrooms: 2, status: 'available', last_verified_at: '2026-09-29', key_features: ['sea front', 'renovation opportunity'] },
  { id: 'PM-107', title: 'Palma Family Villa', location: 'Palma', type: 'villa', price_eur: 1250000, bedrooms: 4, status: 'available', last_verified_at: '2026-09-29', key_features: ['pool', 'parking', 'garden'] },
  { id: 'PM-108', title: 'Inca Renovation House', location: 'Inca', type: 'townhouse', price_eur: 320000, bedrooms: 3, status: 'available', last_verified_at: '2026-09-29', key_features: ['renovation', 'patio', 'investment potential'] }
];

function fold(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[’'`´]/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/s+/g, ' ')
    .trim();
}

function typeCompatible(requested, actual) {
  if (!requested) return true;
  if (requested === actual) return true;
  if (requested === 'house' && ['townhouse', 'villa'].includes(actual)) return true;
  return false;
}

function locationCompatible(requestedLocations, propertyLocation) {
  if (!requestedLocations.length) return true;
  return requestedLocations.includes(propertyLocation);
}

function isFresh(property) {
  const verifiedAt = Date.parse(property.last_verified_at + 'T00:00:00Z');
  const ageDays = Math.floor((referenceDate - verifiedAt) / 86400000);
  return ageDays >= 0 && ageDays <= freshnessDays;
}

function hasFeature(property, feature) {
  return property.key_features.some(item => fold(item) === fold(feature));
}

function matches(property, leadData) {
  if (property.status !== 'available') return false;
  if (!isFresh(property)) return false;
  if (leadData.budget_eur !== null && property.price_eur > leadData.budget_eur) return false;
  if (!locationCompatible(leadData.locations, property.location)) return false;
  if (!typeCompatible(leadData.property_type, property.type)) return false;
  if (leadData.min_bedrooms !== null && property.bedrooms < leadData.min_bedrooms) return false;
  if (!leadData.must_have_features.every(feature => hasFeature(property, feature))) return false;
  return true;
}

function preferenceScore(property, preferredFeatures) {
  return preferredFeatures.reduce((score, feature) => score + (hasFeature(property, feature) ? 1 : 0), 0);
}

const matchesFound = lead.qualification_status === 'matching_ready'
  ? catalogue.filter(property => matches(property, structuredLead)).sort((left, right) => {
      const preferenceDelta = preferenceScore(right, structuredLead.preferred_features) - preferenceScore(left, structuredLead.preferred_features);
      if (preferenceDelta !== 0) return preferenceDelta;
      return left.price_eur - right.price_eur;
    })
  : [];

const compatiblePropertyIds = matchesFound.map(property => property.id);
const escalationReasons = [...lead.escalation_reasons];
if (lead.qualification_status === 'matching_ready' && compatiblePropertyIds.length === 0) {
  escalationReasons.push('no_catalogue_match');
}

return [{
  json: {
    ...lead,
    matched_properties: matchesFound,
    compatible_property_ids: compatiblePropertyIds,
    must_escalate: escalationReasons.length > 0,
    escalation_reasons: escalationReasons
  }
}];

const lead = $json;
const language = lead.detected_language;
const matchCount = lead.compatible_property_ids.length;
let responseDraft = '';

if (language === 'es') {
  if (lead.qualification_status === 'needs_information') {
    responseDraft = 'Gracias por su consulta. Para continuar, necesitamos confirmar ' + lead.missing_fields.join(', ') + '. Un agente revisar\u00e1 la informaci\u00f3n y le responder\u00e1 despu\u00e9s de la aprobaci\u00f3n humana.';
  } else if (matchCount) {
    responseDraft = 'Gracias por su consulta. Hemos identificado ' + matchCount + ' opci\u00f3n' + (matchCount === 1 ? '' : 'es') + ' compatible' + (matchCount === 1 ? '' : 's') + ': ' + lead.compatible_property_ids.join(', ') + '. Un agente comprobar\u00e1 la informaci\u00f3n y revisar\u00e1 el mensaje antes de responder.';
  } else {
    responseDraft = 'Gracias por su consulta. No hemos encontrado una coincidencia fiable en el cat\u00e1logo controlado. Un agente revisar\u00e1 la informaci\u00f3n antes de responder.';
  }
} else if (language === 'de') {
  if (lead.qualification_status === 'needs_information') {
    responseDraft = 'Vielen Dank f\u00fcr Ihre Anfrage. Bitte best\u00e4tigen Sie ' + lead.missing_fields.join(', ') + '. Ein Makler pr\u00fcft die Informationen und best\u00e4tigt die Verf\u00fcgbarkeit, bevor wir antworten.';
  } else if (matchCount) {
    responseDraft = 'Vielen Dank f\u00fcr Ihre Anfrage. Wir haben ' + matchCount + ' passende Option' + (matchCount === 1 ? '' : 'en') + ' gefunden: ' + lead.compatible_property_ids.join(', ') + '. Ein Makler pr\u00fcft die Verf\u00fcgbarkeit und die Informationen, bevor wir antworten.';
  } else {
    responseDraft = 'Vielen Dank f\u00fcr Ihre Anfrage. Im kontrollierten Katalog wurde keine verl?ssliche ?bereinstimmung gefunden. Ein Makler pr\u00fcft die Informationen vor einer Antwort.';
  }
} else {
  if (lead.qualification_status === 'needs_information') {
    responseDraft = 'Thank you for your enquiry. Please confirm ' + lead.missing_fields.join(', ') + '. An agent will review the information before any reply is sent.';
  } else if (matchCount) {
    responseDraft = 'Thank you for your enquiry. We found ' + matchCount + ' compatible option' + (matchCount === 1 ? '' : 's') + ': ' + lead.compatible_property_ids.join(', ') + '. An agent will review the information before any reply is sent.';
  } else {
    responseDraft = 'Thank you for your enquiry. No reliable match was found in the controlled catalogue. An agent will review the information before any reply is sent.';
  }
}

return [{
  json: {
    ...lead,
    response_draft: responseDraft
  }
}];
